import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const p=JSON.parse('{"title":"学生餐营养指南","description":"卫生行业标准《学生餐营养指南》（WS/T 554—2017）可执行整理：家长核对学校食谱的行动清单，出处直达原文 PDF 页码。","frontmatter":{"title":"学生餐营养指南","issuer":"国家卫生计生委（原）","source_tier":"一级来源","version":"WS/T 554—2017","published":"2017-08","source_url":"https://www.chinanutri.cn/fgbz/fgbzjszn/202103/t20210304_224458.html","status":"现行","tags":["学生餐","中小学","营养","校园餐饮","行动清单"],"type":"国标科普","reviewed":false,"description":"卫生行业标准《学生餐营养指南》（WS/T 554—2017）可执行整理：家长核对学校食谱的行动清单，出处直达原文 PDF 页码。"},"headers":[],"relativePath":"guides/student-meals-2017.md","filePath":"guides/student-meals-2017.md"}'),s={name:"guides/student-meals-2017.md"};function o(l,t,n,h,i,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="学生餐营养指南-ws-t-554—2017" tabindex="-1">学生餐营养指南（WS/T 554—2017） <a class="header-anchor" href="#学生餐营养指南-ws-t-554—2017" aria-label="Permalink to &quot;学生餐营养指南（WS/T 554—2017）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方标准原文</strong>，每条&quot;出处&quot;可点击直达原文对应页。本站不构成诊疗建议。</p></div><blockquote><p><strong>原文出处</strong>：原国家卫生计生委发布的卫生行业标准（<a href="https://www.chinanutri.cn/fgbz/fgbzjszn/202103/t20210304_224458.html" target="_blank" rel="noreferrer">中国疾控中心营养与健康所收录页</a>）。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>。</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>标准对学生餐的核心要求：<strong>食物品种多样、分年龄段定量、烹调方式健康</strong>。附录按 6～17 岁各年龄段给出每人每日食物品种及数量供给表（<a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=4" target="_blank" rel="noreferrer">原文·品种表</a>）。</p><h2 id="行动清单-家长核对学校食谱" tabindex="-1">行动清单：家长核对学校食谱 <a class="header-anchor" href="#行动清单-家长核对学校食谱" aria-label="Permalink to &quot;行动清单：家长核对学校食谱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>主食是否多样：米、面、杂粮和薯类搭配，<strong>避免长期只提供一种主食</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=5" target="_blank" rel="noreferrer">原文 P5</a></td></tr><tr><td>是否餐餐有蔬菜、每天提供水果</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=4" target="_blank" rel="noreferrer">原文·品种表</a></td></tr><tr><td>蛋白质来源是否覆盖：畜禽鱼蛋奶+大豆及坚果（品种表按年龄段定量）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=4" target="_blank" rel="noreferrer">原文·品种表</a></td></tr><tr><td>奶类是否每天供应</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=4" target="_blank" rel="noreferrer">原文·品种表</a></td></tr><tr><td>烹调是否少盐少油少糖（去查学校公示的食谱与用盐量）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=5" target="_blank" rel="noreferrer">原文·烹调要求</a></td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>标准怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;孩子在学校吃饱就行&quot;</td><td>标准按年龄段规定<strong>食物品种数与供给量</strong>，不只是吃饱</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=4" target="_blank" rel="noreferrer">原文·品种表</a></td></tr><tr><td>&quot;主食白米饭白馒头最好&quot;</td><td>可用杂粮或薯类部分替代米面，避免长期单一</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/student-meals-2017.pdf#page=5" target="_blank" rel="noreferrer">原文 P5</a></td></tr></tbody></table><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生计生委（原，现国家卫生健康委）</td></tr><tr><td>版本</td><td>WS/T 554—2017（现行）</td></tr><tr><td>发布时间</td><td>2017 年（栏目发布 2021-03-04）</td></tr><tr><td>原文直链</td><td><a href="https://www.chinanutri.cn/fgbz/fgbzjszn/202103/P020210304358480794678.pdf" target="_blank" rel="noreferrer">疾控营养与健康所收录 PDF</a></td></tr></tbody></table>',12)])])}const f=e(s,[["render",o]]);export{p as __pageData,f as default};
